-- Taxonomy: single option names, and the app's option lists as taxonomy categories.
--
-- Generated by supabase/generators/taxonomy_single_names.py from taxonomy_persona_bucket.py,
-- taxonomy_renames.py and the app's copy (supabase/generators/export_app_options.ts). Edit those and
-- regenerate, not this file.
--
-- Part A — no "/" in any option label (owner, 15 Sep 2026). Ids are renamed to match ("rename ids") and
-- every stored reference moves with them:
--   genres                bollywood_filmi → bollywood · bhajan_kirtan → bhajan · punjabi_folk_bhangra → bhangra · garba_dandiya → garba · hiphop_trap → hiphop · rock_metal → rock · edm_synthwave → edm · lofi_chill → lofi · acoustic_unplugged → acoustic · rnb_soul → rnb · jazz_blues → jazz · reggae_dub → reggae
--   instruments           keyboard_synthesizer → keyboard · drums_percussion → drums · drum_machine_sampler → drum_machine
--   person_types          wind_player → flautist
--   verification_id_type  company_pan_gstin → company_pan
-- New options, placed after their parent with the parent's rules and publish state: trap “Trap” (genres, after hiphop) · metal “Metal” (genres, after rock) · blues “Blues” (genres, after jazz) · sampler “Sampler” (instruments, after drum_machine) · company_gstin “GSTIN” (verification_id_type, after company_pan).
-- verification_id_type: company_pan “Company PAN”, company_gstin “GSTIN”. person_types, instruments and
-- genres take every label, sort order and metadata from taxonomy_persona_bucket.py (single names; sort
-- orders shift where an option was added). Flute is only under Flautist: sitarist loses flute_bansuri.
-- Imported text: opportunities.role_required “Singer / Vocalist” → “Singer”; opportunities.role_required “Sitarist / Flutist, Mix Engineer, Male Lead Vocals” → “Sitarist, Flautist, Mix Engineer, Male Lead Vocals”; marketplace_listings.title “Exclusive Trap / Lofi Beat Instrumental License” → “Exclusive Trap Lofi Beat Instrumental License”.
--
-- References updated: profiles.roles, .instruments, .genres (text[]); profiles.specialisations
-- ("<role slug>:<label>"); profiles.headline (onboarding stores the primary role slug there);
-- profiles.discovery_prefs.instrumentExperience keys; profiles.onboarding_draft primaryRole,
-- secondaryRoles, specialisation keys, primaryInstrument, instruments, instrumentExperience keys, genres;
-- profile_role_details.role_slug, details.primary_instrument, details.secondary_instruments;
-- opportunities.genres; marketplace_listings.item_category (instrument items); person_type_instruments;
-- genre_languages. Arrays keep their order and drop a repeat. No table stores verification_id_type
-- slugs, so company_pan_gstin has no references to move.
--
-- Part B — published option categories from the app's copy, each at most 12 options:
-- verification_types (4), work_types (10), profile_visibility (3), link_platforms (10), intents (11), work_modes (4), available_for (9), service_categories (8), pricing_models (5).
-- metadata.app_key holds the value the app writes today, so an option maps to stored profile values
-- without changing them. Labels with a "/" in the app use a single name: Album (app "Album / EP"),
-- Touring (app "Travel / touring"). link_platforms has no JioSaavn (no brand icon; owner, 15 Sep 2026):
-- a jiosaavn option is removed and sort orders stay 1..n.
--
-- persona_bucket: genres are capped at GREATEST(p_limit, 20) (owner, 15 Sep 2026: up to
-- 20 genres per screen); instruments stay at p_limit. Same signature, so the app's call with
-- p_limit 12 now gets up to 20 genres. The function body is taxonomy_persona_bucket.py's.
--
-- Stops before writing if a new slug is already taken in its category. Each block re-reads what it
-- wrote and raises on any difference; the last block asserts that no option label and none of the fixed
-- text columns contains "/", and that no old slug remains anywhere above. Idempotent: on a database
-- already at the new slugs (for example one built from the regenerated earlier migrations) it changes
-- nothing.
--
-- Rollback: not automatic. Re-running the previous versions of the generators restores the old
-- taxonomy rows; stored references would need the renames applied in reverse, and the Part B
-- categories deleted (DELETE FROM public.taxonomy_categories WHERE key IN (...) cascades to options).

-- 1. Stop if a new slug is already taken
DO $guard$
DECLARE
  v_renames jsonb := $json$[{"category_key":"genres","old":"bollywood_filmi","new":"bollywood"},{"category_key":"genres","old":"bhajan_kirtan","new":"bhajan"},{"category_key":"genres","old":"punjabi_folk_bhangra","new":"bhangra"},{"category_key":"genres","old":"garba_dandiya","new":"garba"},{"category_key":"genres","old":"hiphop_trap","new":"hiphop"},{"category_key":"genres","old":"rock_metal","new":"rock"},{"category_key":"genres","old":"edm_synthwave","new":"edm"},{"category_key":"genres","old":"lofi_chill","new":"lofi"},{"category_key":"genres","old":"acoustic_unplugged","new":"acoustic"},{"category_key":"genres","old":"rnb_soul","new":"rnb"},{"category_key":"genres","old":"jazz_blues","new":"jazz"},{"category_key":"genres","old":"reggae_dub","new":"reggae"},{"category_key":"instruments","old":"keyboard_synthesizer","new":"keyboard"},{"category_key":"instruments","old":"drums_percussion","new":"drums"},{"category_key":"instruments","old":"drum_machine_sampler","new":"drum_machine"},{"category_key":"person_types","old":"wind_player","new":"flautist"},{"category_key":"verification_id_type","old":"company_pan_gstin","new":"company_pan"}]$json$;
  v_added jsonb := $json$[{"category_key":"genres","slug":"trap","label":"Trap","parent":"hiphop"},{"category_key":"genres","slug":"metal","label":"Metal","parent":"rock"},{"category_key":"genres","slug":"blues","label":"Blues","parent":"jazz"},{"category_key":"instruments","slug":"sampler","label":"Sampler","parent":"drum_machine"},{"category_key":"verification_id_type","slug":"company_gstin","label":"GSTIN","parent":"company_pan"}]$json$;
  v_clash text;
BEGIN
  SELECT string_agg(r.category_key || '.' || r.old || ' → ' || r.new, ', ') INTO v_clash
  FROM jsonb_to_recordset(v_renames) AS r(category_key text, old text, new text)
  WHERE EXISTS (SELECT 1 FROM public.taxonomy_options o WHERE o.category_key = r.category_key AND o.slug = r.old)
    AND EXISTS (SELECT 1 FROM public.taxonomy_options o WHERE o.category_key = r.category_key AND o.slug = r.new);
  IF v_clash IS NOT NULL THEN
    RAISE EXCEPTION 'taxonomy rename: new slug already exists beside the old one: %', v_clash;
  END IF;

  -- An added option must not exist yet while its parent still has its old slug.
  SELECT string_agg(a.category_key || '.' || a.slug, ', ') INTO v_clash
  FROM jsonb_to_recordset(v_added) AS a(category_key text, slug text, label text, parent text)
  JOIN jsonb_to_recordset(v_renames) AS r(category_key text, old text, new text)
    ON r.category_key = a.category_key AND r.new = a.parent
  WHERE EXISTS (SELECT 1 FROM public.taxonomy_options o WHERE o.category_key = r.category_key AND o.slug = r.old)
    AND EXISTS (SELECT 1 FROM public.taxonomy_options o WHERE o.category_key = a.category_key AND o.slug = a.slug);
  IF v_clash IS NOT NULL THEN
    RAISE EXCEPTION 'taxonomy rename: added slug already exists: %', v_clash;
  END IF;
END
$guard$;

-- 2. Rename options, move their rules, add the split-out options, set labels and order
DO $rename$
DECLARE
  v_renames jsonb := $json$[{"category_key":"genres","old":"bollywood_filmi","new":"bollywood"},{"category_key":"genres","old":"bhajan_kirtan","new":"bhajan"},{"category_key":"genres","old":"punjabi_folk_bhangra","new":"bhangra"},{"category_key":"genres","old":"garba_dandiya","new":"garba"},{"category_key":"genres","old":"hiphop_trap","new":"hiphop"},{"category_key":"genres","old":"rock_metal","new":"rock"},{"category_key":"genres","old":"edm_synthwave","new":"edm"},{"category_key":"genres","old":"lofi_chill","new":"lofi"},{"category_key":"genres","old":"acoustic_unplugged","new":"acoustic"},{"category_key":"genres","old":"rnb_soul","new":"rnb"},{"category_key":"genres","old":"jazz_blues","new":"jazz"},{"category_key":"genres","old":"reggae_dub","new":"reggae"},{"category_key":"instruments","old":"keyboard_synthesizer","new":"keyboard"},{"category_key":"instruments","old":"drums_percussion","new":"drums"},{"category_key":"instruments","old":"drum_machine_sampler","new":"drum_machine"},{"category_key":"person_types","old":"wind_player","new":"flautist"},{"category_key":"verification_id_type","old":"company_pan_gstin","new":"company_pan"}]$json$;
  v_added jsonb := $json$[{"category_key":"genres","slug":"trap","label":"Trap","parent":"hiphop"},{"category_key":"genres","slug":"metal","label":"Metal","parent":"rock"},{"category_key":"genres","slug":"blues","label":"Blues","parent":"jazz"},{"category_key":"instruments","slug":"sampler","label":"Sampler","parent":"drum_machine"},{"category_key":"verification_id_type","slug":"company_gstin","label":"GSTIN","parent":"company_pan"}]$json$;
  v_options jsonb := $json$[{"category_key":"person_types","slug":"singer","label":"Singer","sort_order":1,"metadata":{"group":"vocal","flow":"talent"}},{"category_key":"person_types","slug":"rapper","label":"Rapper","sort_order":2,"metadata":{"group":"vocal","flow":"talent"}},{"category_key":"person_types","slug":"folk_vocalist","label":"Folk Vocalist","sort_order":3,"metadata":{"group":"vocal","flow":"talent"}},{"category_key":"person_types","slug":"voice_artist","label":"Voice Artist","sort_order":4,"metadata":{"group":"vocal","flow":"talent"}},{"category_key":"person_types","slug":"musician","label":"Musician","sort_order":5,"metadata":{"group":"instrumentalist","flow":"talent"}},{"category_key":"person_types","slug":"guitarist","label":"Guitarist","sort_order":6,"metadata":{"group":"instrumentalist","flow":"talent"}},{"category_key":"person_types","slug":"bassist","label":"Bassist","sort_order":7,"metadata":{"group":"instrumentalist","flow":"talent"}},{"category_key":"person_types","slug":"keyboardist","label":"Keyboardist","sort_order":8,"metadata":{"group":"instrumentalist","flow":"talent"}},{"category_key":"person_types","slug":"drummer","label":"Drummer","sort_order":9,"metadata":{"group":"instrumentalist","flow":"talent"}},{"category_key":"person_types","slug":"sitarist","label":"Sitarist","sort_order":10,"metadata":{"group":"instrumentalist","flow":"talent"}},{"category_key":"person_types","slug":"violinist","label":"Violinist","sort_order":11,"metadata":{"group":"instrumentalist","flow":"talent"}},{"category_key":"person_types","slug":"flautist","label":"Flautist","sort_order":12,"metadata":{"group":"instrumentalist","flow":"talent"}},{"category_key":"person_types","slug":"composer","label":"Composer","sort_order":13,"metadata":{"group":"creator","flow":"talent"}},{"category_key":"person_types","slug":"lyricist","label":"Lyricist","sort_order":14,"metadata":{"group":"creator","flow":"talent"}},{"category_key":"person_types","slug":"arranger","label":"Vocal Arranger","sort_order":15,"metadata":{"group":"creator","flow":"talent"}},{"category_key":"person_types","slug":"music_director","label":"Music Director","sort_order":16,"metadata":{"group":"creator","flow":"talent"}},{"category_key":"person_types","slug":"producer","label":"Music Producer","sort_order":17,"metadata":{"group":"creator","flow":"talent"}},{"category_key":"person_types","slug":"beatmaker","label":"Beatmaker","sort_order":18,"metadata":{"group":"creator","flow":"talent"}},{"category_key":"person_types","slug":"sound_engineer","label":"Sound Engineer","sort_order":19,"metadata":{"group":"technical","flow":"talent"}},{"category_key":"person_types","slug":"mixing_engineer","label":"Mixing Engineer","sort_order":20,"metadata":{"group":"technical","flow":"talent"}},{"category_key":"person_types","slug":"mastering_engineer","label":"Mastering Engineer","sort_order":21,"metadata":{"group":"technical","flow":"talent"}},{"category_key":"person_types","slug":"sound_designer","label":"Sound Designer","sort_order":22,"metadata":{"group":"technical","flow":"talent"}},{"category_key":"person_types","slug":"dj","label":"DJ","sort_order":23,"metadata":{"group":"media","flow":"talent"}},{"category_key":"person_types","slug":"rj","label":"RJ","sort_order":24,"metadata":{"group":"media","flow":"talent"}},{"category_key":"person_types","slug":"podcaster","label":"Podcaster","sort_order":25,"metadata":{"group":"media","flow":"talent"}},{"category_key":"person_types","slug":"music_teacher","label":"Music Teacher","sort_order":26,"metadata":{"group":"education","flow":"talent"}},{"category_key":"person_types","slug":"studio","label":"Recording Studio","sort_order":27,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"music_label","label":"Music Label","sort_order":28,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"venue","label":"Venue","sort_order":29,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"event_organizer","label":"Event Organizer","sort_order":30,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"booking_agency","label":"Booking Agency","sort_order":31,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"artist_manager","label":"Artist Manager","sort_order":32,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"production_house","label":"Production House","sort_order":33,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"music_school","label":"Music School","sort_order":34,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"dealer","label":"Dealer","sort_order":35,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"rental_provider","label":"Rental Provider","sort_order":36,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"music_publisher","label":"Music Publisher","sort_order":37,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"a_and_r","label":"A&R","sort_order":38,"metadata":{"group":"business","flow":"business"}},{"category_key":"person_types","slug":"other","label":"Other","sort_order":39,"metadata":{"group":"other","flow":"talent"}},{"category_key":"instruments","slug":"acoustic_guitar","label":"Acoustic Guitar","sort_order":1,"metadata":{"family":"guitar"}},{"category_key":"instruments","slug":"keyboard","label":"Keyboard","sort_order":2,"metadata":{"family":"keys"}},{"category_key":"instruments","slug":"piano","label":"Piano","sort_order":3,"metadata":{"family":"keys"}},{"category_key":"instruments","slug":"electric_guitar","label":"Electric Guitar","sort_order":4,"metadata":{"family":"guitar"}},{"category_key":"instruments","slug":"drums","label":"Drums","sort_order":5,"metadata":{"family":"percussion"}},{"category_key":"instruments","slug":"tabla","label":"Tabla","sort_order":6,"metadata":{"family":"percussion"}},{"category_key":"instruments","slug":"bass_guitar","label":"Bass Guitar","sort_order":7,"metadata":{"family":"guitar"}},{"category_key":"instruments","slug":"flute_bansuri","label":"Flute (Bansuri)","sort_order":8,"metadata":{"family":"wind"}},{"category_key":"instruments","slug":"violin","label":"Violin","sort_order":9,"metadata":{"family":"bowed"}},{"category_key":"instruments","slug":"harmonium","label":"Harmonium","sort_order":10,"metadata":{"family":"keys"}},{"category_key":"instruments","slug":"sitar","label":"Sitar","sort_order":11,"metadata":{"family":"indian_string"}},{"category_key":"instruments","slug":"dholak","label":"Dholak","sort_order":12,"metadata":{"family":"percussion"}},{"category_key":"instruments","slug":"dj_controller","label":"DJ Controller","sort_order":13,"metadata":{"family":"electronic"}},{"category_key":"instruments","slug":"drum_machine","label":"Drum Machine","sort_order":14,"metadata":{"family":"electronic"}},{"category_key":"instruments","slug":"sampler","label":"Sampler","sort_order":15,"metadata":{"family":"electronic"}},{"category_key":"instruments","slug":"saxophone","label":"Saxophone","sort_order":16,"metadata":{"family":"wind"}},{"category_key":"instruments","slug":"ukulele","label":"Ukulele","sort_order":17,"metadata":{"family":"guitar"}},{"category_key":"instruments","slug":"cajon","label":"Cajón","sort_order":18,"metadata":{"family":"percussion"}},{"category_key":"instruments","slug":"santoor","label":"Santoor","sort_order":19,"metadata":{"family":"indian_string"}},{"category_key":"instruments","slug":"mridangam","label":"Mridangam","sort_order":20,"metadata":{"family":"percussion"}},{"category_key":"instruments","slug":"veena","label":"Veena","sort_order":21,"metadata":{"family":"indian_string"}},{"category_key":"instruments","slug":"sarangi","label":"Sarangi","sort_order":22,"metadata":{"family":"bowed"}},{"category_key":"instruments","slug":"cello","label":"Cello","sort_order":23,"metadata":{"family":"bowed"}},{"category_key":"instruments","slug":"trumpet","label":"Trumpet","sort_order":24,"metadata":{"family":"wind"}},{"category_key":"instruments","slug":"sarod","label":"Sarod","sort_order":25,"metadata":{"family":"indian_string"}},{"category_key":"instruments","slug":"shehnai","label":"Shehnai","sort_order":26,"metadata":{"family":"wind"}},{"category_key":"instruments","slug":"tanpura","label":"Tanpura","sort_order":27,"metadata":{"family":"indian_string"}},{"category_key":"instruments","slug":"ghatam","label":"Ghatam","sort_order":28,"metadata":{"family":"percussion"}},{"category_key":"instruments","slug":"kanjira","label":"Kanjira","sort_order":29,"metadata":{"family":"percussion"}},{"category_key":"instruments","slug":"clarinet","label":"Clarinet","sort_order":30,"metadata":{"family":"wind"}},{"category_key":"instruments","slug":"nadaswaram","label":"Nadaswaram","sort_order":31,"metadata":{"family":"wind"}},{"category_key":"instruments","slug":"mandolin","label":"Mandolin","sort_order":32,"metadata":{"family":"guitar"}},{"category_key":"instruments","slug":"double_bass","label":"Double Bass","sort_order":33,"metadata":{"family":"bowed"}},{"category_key":"instruments","slug":"viola","label":"Viola","sort_order":34,"metadata":{"family":"bowed"}},{"category_key":"instruments","slug":"harmonica","label":"Harmonica","sort_order":35,"metadata":{"family":"wind"}},{"category_key":"genres","slug":"bollywood","label":"Bollywood","sort_order":1,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"punjabi_pop","label":"Punjabi Pop","sort_order":2,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"hindustani_classical","label":"Hindustani Classical","sort_order":3,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"carnatic_classical","label":"Carnatic Classical","sort_order":4,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"sufi_devotional","label":"Sufi Devotional","sort_order":5,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"bhajan","label":"Bhajan","sort_order":6,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"ghazal","label":"Ghazal","sort_order":7,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"qawwali","label":"Qawwali","sort_order":8,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"bhangra","label":"Bhangra","sort_order":9,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"kollywood","label":"Tamil Film (Kollywood)","sort_order":10,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"tollywood","label":"Telugu Film (Tollywood)","sort_order":11,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"mollywood","label":"Malayalam Film (Mollywood)","sort_order":12,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"sandalwood","label":"Kannada Film (Sandalwood)","sort_order":13,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"rabindra_sangeet","label":"Rabindra Sangeet","sort_order":14,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"lavani","label":"Lavani","sort_order":15,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"garba","label":"Garba","sort_order":16,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"bihu","label":"Bihu","sort_order":17,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"bhojpuri_folk","label":"Bhojpuri Folk","sort_order":18,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"gaana","label":"Gaana","sort_order":19,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"baul","label":"Baul","sort_order":20,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"natya_sangeet","label":"Natya Sangeet","sort_order":21,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"rajasthani_folk","label":"Rajasthani Folk","sort_order":22,"metadata":{"scope":"regional"}},{"category_key":"genres","slug":"indie_pop","label":"Indie Pop","sort_order":23,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"hiphop","label":"Hip Hop","sort_order":24,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"trap","label":"Trap","sort_order":25,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"rock","label":"Rock","sort_order":26,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"metal","label":"Metal","sort_order":27,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"edm","label":"EDM","sort_order":28,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"lofi","label":"Lofi","sort_order":29,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"acoustic","label":"Acoustic","sort_order":30,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"fusion","label":"Fusion","sort_order":31,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"rnb","label":"R&B","sort_order":32,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"jazz","label":"Jazz","sort_order":33,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"blues","label":"Blues","sort_order":34,"metadata":{"scope":"universal"}},{"category_key":"genres","slug":"reggae","label":"Reggae","sort_order":35,"metadata":{"scope":"universal"}},{"category_key":"verification_id_type","slug":"company_pan","label":"Company PAN","sort_order":4,"metadata":null},{"category_key":"verification_id_type","slug":"company_gstin","label":"GSTIN","sort_order":5,"metadata":null}]$json$;
  a record;
BEGIN
  -- New row per renamed option, carrying the old row's publish state and creation time.
  INSERT INTO public.taxonomy_options (category_key, slug, label, sort_order, is_published, metadata, created_at)
  SELECT o.category_key, r.new, o.label, o.sort_order, o.is_published, o.metadata, o.created_at
  FROM jsonb_to_recordset(v_renames) AS r(category_key text, old text, new text)
  JOIN public.taxonomy_options o ON o.category_key = r.category_key AND o.slug = r.old
  ON CONFLICT (category_key, slug) DO NOTHING;

  INSERT INTO public.person_type_instruments (person_type_slug, instrument_slug)
  SELECT coalesce(rp.new, p.person_type_slug), coalesce(ri.new, p.instrument_slug)
  FROM public.person_type_instruments p
  LEFT JOIN jsonb_to_recordset(v_renames) AS rp(category_key text, old text, new text)
    ON rp.category_key = 'person_types' AND rp.old = p.person_type_slug
  LEFT JOIN jsonb_to_recordset(v_renames) AS ri(category_key text, old text, new text)
    ON ri.category_key = 'instruments' AND ri.old = p.instrument_slug
  WHERE rp.old IS NOT NULL OR ri.old IS NOT NULL
  ON CONFLICT (person_type_slug, instrument_slug) DO NOTHING;

  INSERT INTO public.genre_languages (genre_slug, language_slug)
  SELECT r.new, g.language_slug
  FROM public.genre_languages g
  JOIN jsonb_to_recordset(v_renames) AS r(category_key text, old text, new text)
    ON r.category_key = 'genres' AND r.old = g.genre_slug
  ON CONFLICT (genre_slug, language_slug) DO NOTHING;

  -- Old rows go; their rule rows were copied above and cascade with them.
  DELETE FROM public.taxonomy_options o
  USING jsonb_to_recordset(v_renames) AS r(category_key text, old text, new text)
  WHERE o.category_key = r.category_key AND o.slug = r.old;

  -- Split-out options: created once, with the parent's publish state and rules.
  FOR a IN SELECT * FROM jsonb_to_recordset(v_added) AS x(category_key text, slug text, label text, parent text) LOOP
    INSERT INTO public.taxonomy_options (category_key, slug, label, sort_order, is_published, metadata)
    SELECT p.category_key, a.slug, a.label, p.sort_order, p.is_published, p.metadata
    FROM public.taxonomy_options p
    WHERE p.category_key = a.category_key AND p.slug = a.parent
    ON CONFLICT (category_key, slug) DO NOTHING;
    IF FOUND THEN
      IF a.category_key = 'instruments' THEN
        INSERT INTO public.person_type_instruments (person_type_slug, instrument_slug)
        SELECT p.person_type_slug, a.slug FROM public.person_type_instruments p WHERE p.instrument_slug = a.parent
        ON CONFLICT (person_type_slug, instrument_slug) DO NOTHING;
      ELSIF a.category_key = 'genres' THEN
        INSERT INTO public.genre_languages (genre_slug, language_slug)
        SELECT a.slug, g.language_slug FROM public.genre_languages g WHERE g.genre_slug = a.parent
        ON CONFLICT (genre_slug, language_slug) DO NOTHING;
      END IF;
    END IF;
  END LOOP;

  DELETE FROM public.person_type_instruments
  WHERE (person_type_slug, instrument_slug) IN (('sitarist', 'flute_bansuri'));

  UPDATE public.taxonomy_options o SET label = r.label, sort_order = r.sort_order, metadata = r.metadata
  FROM jsonb_to_recordset(v_options) AS r(category_key text, slug text, label text, sort_order int, metadata jsonb)
  WHERE o.category_key = r.category_key AND o.slug = r.slug
    AND (o.label, o.sort_order, o.metadata) IS DISTINCT FROM (r.label, r.sort_order, r.metadata);

  IF (SELECT count(*) FROM jsonb_to_recordset(v_options) AS r(category_key text, slug text, label text, sort_order int, metadata jsonb)
      JOIN public.taxonomy_options o ON o.category_key = r.category_key AND o.slug = r.slug
      WHERE (o.label, o.sort_order, o.metadata) IS NOT DISTINCT FROM (r.label, r.sort_order, r.metadata))
     <> jsonb_array_length(v_options) THEN
    RAISE EXCEPTION 'taxonomy rename: stored options differ from the payload';
  END IF;
END
$rename$;

-- 3. Option categories from the app's copy (9 categories, 64 options)
