":"intents","slug":"sell_equipment","label":"Sell Equipment","metadata":{"app_key":"Sell Equipment"},"sort_order":7},{"category_key":"intents","slug":"join_communities","label":"Join Communities","metadata":{"app_key":"Join Communities"},"sort_order":8},{"category_key":"intents","slug":"discover_music","label":"Discover Music","metadata":{"app_key":"Discover Music"},"sort_order":9},{"category_key":"intents","slug":"promote_my_work","label":"Promote My Work","metadata":{"app_key":"Promote My Work"},"sort_order":10},{"category_key":"intents","slug":"build_professional_network","label":"Build Professional Network","metadata":{"app_key":"Build Professional Network"},"sort_order":11},{"category_key":"work_modes","slug":"in_person","label":"In person","metadata":{"app_key":"in-person","description":"Studios, stages, sets"},"sort_order":1},{"category_key":"work_modes","slug":"remote","label":"Remote","metadata":{"app_key":"remote","description":"Files, stems, online sessions"},"sort_order":2},{"category_key":"work_modes","slug":"hybrid","label":"Hybrid","metadata":{"app_key":"hybrid","description":"A mix of both"},"sort_order":3},{"category_key":"work_modes","slug":"touring","label":"Touring","metadata":{"app_key":"touring","description":"Happy to travel for work"},"sort_order":4},{"category_key":"available_for","slug":"shows","label":"Shows","metadata":{"app_key":"Shows"},"sort_order":1},{"category_key":"available_for","slug":"session_work","label":"Session Work","metadata":{"app_key":"Session Work"},"sort_order":2},{"category_key":"available_for","slug":"collaborations","label":"Collaborations","metadata":{"app_key":"Collaborations"},"sort_order":3},{"category_key":"available_for","slug":"projects","label":"Projects","metadata":{"app_key":"Projects"},"sort_order":4},{"category_key":"available_for","slug":"teaching","label":"Teaching","metadata":{"app_key":"Teaching"},"sort_order":5},{"category_key":"available_for","slug":"recording","label":"Recording","metadata":{"app_key":"Recording"},"sort_order":6},{"category_key":"available_for","slug":"production","label":"Production","metadata":{"app_key":"Production"},"sort_order":7},{"category_key":"available_for","slug":"freelance_work","label":"Freelance Work","metadata":{"app_key":"Freelance Work"},"sort_order":8},{"category_key":"available_for","slug":"touring","label":"Touring","metadata":{"app_key":"Touring"},"sort_order":9},{"category_key":"service_categories","slug":"vocals","label":"Session vocals","metadata":{"app_key":"vocals"},"sort_order":1},{"category_key":"service_categories","slug":"mixing","label":"Mixing","metadata":{"app_key":"mixing"},"sort_order":2},{"category_key":"service_categories","slug":"mastering","label":"Mastering","metadata":{"app_key":"mastering"},"sort_order":3},{"category_key":"service_categories","slug":"production","label":"Production","metadata":{"app_key":"production"},"sort_order":4},{"category_key":"service_categories","slug":"instrument","label":"Session instrument","metadata":{"app_key":"instrument"},"sort_order":5},{"category_key":"service_categories","slug":"songwriting","label":"Songwriting","metadata":{"app_key":"songwriting"},"sort_order":6},{"category_key":"service_categories","slug":"live","label":"Live performance","metadata":{"app_key":"live"},"sort_order":7},{"category_key":"service_categories","slug":"studio","label":"Studio time","metadata":{"app_key":"studio"},"sort_order":8},{"category_key":"pricing_models","slug":"hourly","label":"Per hour","metadata":{"app_key":"hourly"},"sort_order":1},{"category_key":"pricing_models","slug":"per_song","label":"Per song","metadata":{"app_key":"per_song"},"sort_order":2},{"category_key":"pricing_models","slug":"per_day","label":"Per day","metadata":{"app_key":"per_day"},"sort_order":3},{"category_key":"pricing_models","slug":"package","label":"Packages only","metadata":{"app_key":"package"},"sort_order":4},{"category_key":"pricing_models","slug":"custom","label":"Custom quote","metadata":{"app_key":"custom"},"sort_order":5}]$json$;
BEGIN
  INSERT INTO public.taxonomy_categories (key, label, description)
  SELECT r.key, r.label, r.description FROM jsonb_to_recordset(v_categories) AS r(key text, label text, description text)
  ON CONFLICT (key) DO UPDATE SET label = EXCLUDED.label, description = EXCLUDED.description
  WHERE (taxonomy_categories.label, taxonomy_categories.description) IS DISTINCT FROM (EXCLUDED.label, EXCLUDED.description);

  -- Platforms no longer offered.
  DELETE FROM public.taxonomy_options
  WHERE category_key = 'link_platforms' AND slug IN ('jiosaavn');

  INSERT INTO public.taxonomy_options (category_key, slug, label, sort_order, metadata)
  SELECT r.category_key, r.slug, r.label, r.sort_order, r.metadata
  FROM jsonb_to_recordset(v_options) AS r(category_key text, slug text, label text, sort_order int, metadata jsonb)
  ON CONFLICT (category_key, slug) DO UPDATE SET label = EXCLUDED.label, sort_order = EXCLUDED.sort_order,
    metadata = EXCLUDED.metadata
  WHERE (taxonomy_options.label, taxonomy_options.sort_order, taxonomy_options.metadata)
        IS DISTINCT FROM (EXCLUDED.label, EXCLUDED.sort_order, EXCLUDED.metadata);

  IF (SELECT count(*) FROM jsonb_to_recordset(v_categories) AS r(key text, label text, description text)
      JOIN public.taxonomy_categories c ON c.key = r.key
      WHERE (c.label, c.description) IS NOT DISTINCT FROM (r.label, r.description))
     <> jsonb_array_length(v_categories) THEN
    RAISE EXCEPTION 'taxonomy categories import: stored rows differ from the payload';
  END IF;
  IF (SELECT count(*) FROM jsonb_to_recordset(v_options) AS r(category_key text, slug text, label text, sort_order int, metadata jsonb)
      JOIN public.taxonomy_options o ON o.category_key = r.category_key AND o.slug = r.slug
      WHERE (o.label, o.sort_order, o.metadata) IS NOT DISTINCT FROM (r.label, r.sort_order, r.metadata))
     <> jsonb_array_length(v_options) THEN
    RAISE EXCEPTION 'taxonomy options import: stored rows differ from the payload';
  END IF;
  IF EXISTS (SELECT 1 FROM public.taxonomy_options
             WHERE category_key = 'link_platforms' AND slug IN ('jiosaavn'))
     OR EXISTS (SELECT 1 FROM (SELECT sort_order, row_number() OVER (ORDER BY sort_order, slug) AS n
                               FROM public.taxonomy_options WHERE category_key = 'link_platforms') x
                WHERE x.sort_order <> x.n) THEN
    RAISE EXCEPTION 'link_platforms: a removed platform remains or sort orders are not 1..n';
  END IF;
END
$import$;

-- 4. Stored references to renamed slugs
DO $refs$
DECLARE
  v_renames jsonb := $json${"genres":{"bollywood_filmi":"bollywood","bhajan_kirtan":"bhajan","punjabi_folk_bhangra":"bhangra","garba_dandiya":"garba","hiphop_trap":"hiphop","rock_metal":"rock","edm_synthwave":"edm","lofi_chill":"lofi","acoustic_unplugged":"acoustic","rnb_soul":"rnb","jazz_blues":"jazz","reggae_dub":"reggae"},"instruments":{"keyboard_synthesizer":"keyboard","drums_percussion":"drums","drum_machine_sampler":"drum_machine"},"person_types":{"wind_player":"flautist"},"verification_id_type":{"company_pan_gstin":"company_pan"}}$json$;
BEGIN
  UPDATE public.profiles t SET roles = (SELECT coalesce(array_agg(d.v ORDER BY d.o), '{}') FROM (SELECT DISTINCT ON (y.v) y.v, u.o FROM unnest(t.roles) WITH ORDINALITY AS u(x, o) CROSS JOIN LATERAL (SELECT coalesce(v_renames->'person_types'->>u.x, u.x) AS v) y ORDER BY y.v, u.o) d)
  WHERE t.roles && ARRAY(SELECT jsonb_object_keys(v_renames->'person_types'));
  UPDATE public.profiles t SET instruments = (SELECT coalesce(array_agg(d.v ORDER BY d.o), '{}') FROM (SELECT DISTINCT ON (y.v) y.v, u.o FROM unnest(t.instruments) WITH ORDINALITY AS u(x, o) CROSS JOIN LATERAL (SELECT coalesce(v_renames->'instruments'->>u.x, u.x) AS v) y ORDER BY y.v, u.o) d)
  WHERE t.instruments && ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'));
  UPDATE public.profiles t SET genres = (SELECT coalesce(array_agg(d.v ORDER BY d.o), '{}') FROM (SELECT DISTINCT ON (y.v) y.v, u.o FROM unnest(t.genres) WITH ORDINALITY AS u(x, o) CROSS JOIN LATERAL (SELECT coalesce(v_renames->'genres'->>u.x, u.x) AS v) y ORDER BY y.v, u.o) d)
  WHERE t.genres && ARRAY(SELECT jsonb_object_keys(v_renames->'genres'));
  UPDATE public.profiles t SET specialisations = (SELECT coalesce(array_agg(d.v ORDER BY d.o), '{}') FROM (SELECT DISTINCT ON (y.v) y.v, u.o FROM unnest(t.specialisations) WITH ORDINALITY AS u(x, o) CROSS JOIN LATERAL (SELECT CASE WHEN position(':' in u.x) > 1 AND v_renames->'person_types' ? split_part(u.x, ':', 1) THEN (v_renames->'person_types'->>split_part(u.x, ':', 1)) || substr(u.x, position(':' in u.x)) ELSE u.x END AS v) y ORDER BY y.v, u.o) d)
  WHERE EXISTS (SELECT 1 FROM unnest(t.specialisations) AS s(x) WHERE position(':' in s.x) > 1 AND v_renames->'person_types' ? split_part(s.x, ':', 1));
  UPDATE public.profiles t SET headline = v_renames->'person_types'->>t.headline
  WHERE t.headline = ANY (ARRAY(SELECT jsonb_object_keys(v_renames->'person_types')));
  UPDATE public.profiles t SET discovery_prefs = jsonb_set(t.discovery_prefs, '{instrumentExperience}', (SELECT coalesce(jsonb_object_agg(d.k, d.v), '{}') FROM (SELECT DISTINCT ON (coalesce(v_renames->'instruments'->>j.key, j.key)) coalesce(v_renames->'instruments'->>j.key, j.key) AS k, j.value AS v FROM jsonb_each(t.discovery_prefs->'instrumentExperience') AS j ORDER BY coalesce(v_renames->'instruments'->>j.key, j.key), v_renames->'instruments' ? j.key) d))
  WHERE jsonb_typeof(t.discovery_prefs->'instrumentExperience') = 'object' AND t.discovery_prefs->'instrumentExperience' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'));
  UPDATE public.profiles t SET onboarding_draft = jsonb_set(t.onboarding_draft, '{primaryRole}', to_jsonb(v_renames->'person_types'->>(t.onboarding_draft->>'primaryRole')))
  WHERE jsonb_typeof(t.onboarding_draft->'primaryRole') = 'string' AND v_renames->'person_types' ? (t.onboarding_draft->>'primaryRole');
  UPDATE public.profiles t SET onboarding_draft = jsonb_set(t.onboarding_draft, '{secondaryRoles}', (SELECT coalesce(jsonb_agg(d.v ORDER BY d.o), '[]') FROM (SELECT DISTINCT ON (y.v) y.v, e.o FROM jsonb_array_elements(t.onboarding_draft->'secondaryRoles') WITH ORDINALITY AS e(x, o) CROSS JOIN LATERAL (SELECT CASE WHEN jsonb_typeof(e.x) = 'string' AND v_renames->'person_types' ? (e.x #>> '{}') THEN to_jsonb(v_renames->'person_types'->>(e.x #>> '{}')) ELSE e.x END AS v) y ORDER BY y.v, e.o) d))
  WHERE jsonb_typeof(t.onboarding_draft->'secondaryRoles') = 'array' AND t.onboarding_draft->'secondaryRoles' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'person_types'));
  UPDATE public.profiles t SET onboarding_draft = jsonb_set(t.onboarding_draft, '{specialisation}', (SELECT coalesce(jsonb_object_agg(d.k, d.v), '{}') FROM (SELECT DISTINCT ON (coalesce(v_renames->'person_types'->>j.key, j.key)) coalesce(v_renames->'person_types'->>j.key, j.key) AS k, j.value AS v FROM jsonb_each(t.onboarding_draft->'specialisation') AS j ORDER BY coalesce(v_renames->'person_types'->>j.key, j.key), v_renames->'person_types' ? j.key) d))
  WHERE jsonb_typeof(t.onboarding_draft->'specialisation') = 'object' AND t.onboarding_draft->'specialisation' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'person_types'));
  UPDATE public.profiles t SET onboarding_draft = jsonb_set(t.onboarding_draft, '{primaryInstrument}', to_jsonb(v_renames->'instruments'->>(t.onboarding_draft->>'primaryInstrument')))
  WHERE jsonb_typeof(t.onboarding_draft->'primaryInstrument') = 'string' AND v_renames->'instruments' ? (t.onboarding_draft->>'primaryInstrument');
  UPDATE public.profiles t SET onboarding_draft = jsonb_set(t.onboarding_draft, '{instruments}', (SELECT coalesce(jsonb_agg(d.v ORDER BY d.o), '[]') FROM (SELECT DISTINCT ON (y.v) y.v, e.o FROM jsonb_array_elements(t.onboarding_draft->'instruments') WITH ORDINALITY AS e(x, o) CROSS JOIN LATERAL (SELECT CASE WHEN jsonb_typeof(e.x) = 'string' AND v_renames->'instruments' ? (e.x #>> '{}') THEN to_jsonb(v_renames->'instruments'->>(e.x #>> '{}')) ELSE e.x END AS v) y ORDER BY y.v, e.o) d))
  WHERE jsonb_typeof(t.onboarding_draft->'instruments') = 'array' AND t.onboarding_draft->'instruments' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'));
  UPDATE public.profiles t SET onboarding_draft = jsonb_set(t.onboarding_draft, '{instrumentExperience}', (SELECT coalesce(jsonb_object_agg(d.k, d.v), '{}') FROM (SELECT DISTINCT ON (coalesce(v_renames->'instruments'->>j.key, j.key)) coalesce(v_renames->'instruments'->>j.key, j.key) AS k, j.value AS v FROM jsonb_each(t.onboarding_draft->'instrumentExperience') AS j ORDER BY coalesce(v_renames->'instruments'->>j.key, j.key), v_renames->'instruments' ? j.key) d))
  WHERE jsonb_typeof(t.onboarding_draft->'instrumentExperience') = 'object' AND t.onboarding_draft->'instrumentExperience' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'));
  UPDATE public.profiles t SET onboarding_draft = jsonb_set(t.onboarding_draft, '{genres}', (SELECT coalesce(jsonb_agg(d.v ORDER BY d.o), '[]') FROM (SELECT DISTINCT ON (y.v) y.v, e.o FROM jsonb_array_elements(t.onboarding_draft->'genres') WITH ORDINALITY AS e(x, o) CROSS JOIN LATERAL (SELECT CASE WHEN jsonb_typeof(e.x) = 'string' AND v_renames->'genres' ? (e.x #>> '{}') THEN to_jsonb(v_renames->'genres'->>(e.x #>> '{}')) ELSE e.x END AS v) y ORDER BY y.v, e.o) d))
  WHERE jsonb_typeof(t.onboarding_draft->'genres') = 'array' AND t.onboarding_draft->'genres' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'genres'));
  UPDATE public.profile_role_details t SET details = jsonb_set(t.details, '{primary_instrument}', to_jsonb(v_renames->'instruments'->>(t.details->>'primary_instrument'))), updated_at = now()
  WHERE jsonb_typeof(t.details->'primary_instrument') = 'string' AND v_renames->'instruments' ? (t.details->>'primary_instrument');
  UPDATE public.profile_role_details t SET details = jsonb_set(t.details, '{secondary_instruments}', (SELECT coalesce(jsonb_agg(d.v ORDER BY d.o), '[]') FROM (SELECT DISTINCT ON (y.v) y.v, e.o FROM jsonb_array_elements(t.details->'secondary_instruments') WITH ORDINALITY AS e(x, o) CROSS JOIN LATERAL (SELECT CASE WHEN jsonb_typeof(e.x) = 'string' AND v_renames->'instruments' ? (e.x #>> '{}') THEN to_jsonb(v_renames->'instruments'->>(e.x #>> '{}')) ELSE e.x END AS v) y ORDER BY y.v, e.o) d)), updated_at = now()
  WHERE jsonb_typeof(t.details->'secondary_instruments') = 'array' AND t.details->'secondary_instruments' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'));
  UPDATE public.opportunities t SET genres = (SELECT coalesce(array_agg(d.v ORDER BY d.o), '{}') FROM (SELECT DISTINCT ON (y.v) y.v, u.o FROM unnest(t.genres) WITH ORDINALITY AS u(x, o) CROSS JOIN LATERAL (SELECT coalesce(v_renames->'genres'->>u.x, u.x) AS v) y ORDER BY y.v, u.o) d), updated_at = now()
  WHERE t.genres && ARRAY(SELECT jsonb_object_keys(v_renames->'genres'));

  -- A role detail row moves to the new role unless the profile already has one there (the check
  -- below then stops the migration).
  UPDATE public.profile_role_details t SET role_slug = v_renames->'person_types'->>t.role_slug, updated_at = now()
  WHERE v_renames->'person_types' ? t.role_slug
    AND NOT EXISTS (SELECT 1 FROM public.profile_role_details n
                    WHERE n.profile_id = t.profile_id AND n.role_slug = v_renames->'person_types'->>t.role_slug);

  UPDATE public.marketplace_listings t SET item_category = v_renames->'instruments'->>t.item_category, updated_at = now()
  WHERE t.item_category_kind IS DISTINCT FROM 'equipment' AND v_renames->'instruments' ? t.item_category;
END
$refs$;

-- 5. Imported text without "/"
DO $text$
DECLARE
  v_fixes jsonb := $json$[{"table":"opportunities","column":"role_required","old":"Singer / Vocalist","new":"Singer"},{"table":"opportunities","column":"role_required","old":"Sitarist / Flutist, Mix Engineer, Male Lead Vocals","new":"Sitarist, Flautist, Mix Engineer, Male Lead Vocals"},{"table":"marketplace_listings","column":"title","old":"Exclusive Trap / Lofi Beat Instrumental License","new":"Exclusive Trap Lofi Beat Instrumental License"}]$json$;
BEGIN
  UPDATE public.opportunities t SET role_required = r.new, updated_at = now()
  FROM jsonb_to_recordset(v_fixes) AS r("table" text, "column" text, old text, new text)
  WHERE r."table" = 'opportunities' AND r."column" = 'role_required' AND t.role_required = r.old;

  UPDATE public.marketplace_listings t SET title = r.new, updated_at = now()
  FROM jsonb_to_recordset(v_fixes) AS r("table" text, "column" text, old text, new text)
  WHERE r."table" = 'marketplace_listings' AND r."column" = 'title' AND t.title = r.old;
END
$text$;

-- 6. persona_bucket: up to 20 genres per screen, other categories on p_limit
CREATE OR REPLACE FUNCTION public.persona_bucket(
  p_primary   text,
  p_secondary text[] DEFAULT '{}',
  p_languages text[] DEFAULT '{}',
  p_limit     int    DEFAULT 12
)
RETURNS TABLE (category_key text, slug text, label text, display_order int)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public
AS $fn$
#variable_conflict use_column
DECLARE
  v_roles text[] := array_append(coalesce(p_secondary, '{}'), p_primary);
BEGIN
  IF p_limit IS NULL OR p_limit < 1 THEN
    RAISE EXCEPTION 'persona_bucket: p_limit must be at least 1, got %', p_limit;
  END IF;
  IF cardinality(coalesce(p_secondary, '{}')) > 2 THEN
    RAISE EXCEPTION 'persona_bucket: at most 2 secondary person types, got %', cardinality(p_secondary);
  END IF;
  IF (SELECT count(DISTINCT x) FROM unnest(coalesce(p_secondary, '{}')) x) <> cardinality(coalesce(p_secondary, '{}')) THEN
    RAISE EXCEPTION 'persona_bucket: secondary person types repeat: %', p_secondary;
  END IF;
  IF p_primary = ANY (coalesce(p_secondary, '{}')) THEN
    RAISE EXCEPTION 'persona_bucket: secondary person type % repeats the primary', p_primary;
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_roles) r
    WHERE NOT EXISTS (SELECT 1 FROM taxonomy_options o
                      JOIN taxonomy_categories c ON c.key = o.category_key AND c.is_published
                      WHERE o.category_key = 'person_types' AND o.slug = r AND o.is_published)
  ) THEN
    RAISE EXCEPTION 'persona_bucket: unknown or unpublished person type in %', v_roles;
  END IF;

  -- tier 0 ranks first: instruments the primary person type allows; regional genres a selected
  -- language unlocks. Within a tier, sort_order (popularity). Instruments are capped at p_limit,
  -- genres at GREATEST(p_limit, 20).
  RETURN QUERY
  WITH candidates AS (
    SELECT o.category_key AS cat, o.slug AS opt_slug, o.label AS opt_label, o.sort_order AS rank_order,
           CASE WHEN EXISTS (SELECT 1 FROM person_type_instruments p0
                             WHERE p0.instrument_slug = o.slug AND p0.person_type_slug = p_primary)
                THEN 0 ELSE 1 END AS tier
    FROM taxonomy_options o
    JOIN taxonomy_categories c ON c.key = o.category_key AND c.is_published
    WHERE o.category_key = 'instruments' AND o.is_published
      AND EXISTS (SELECT 1 FROM person_type_instruments pti
                  WHERE pti.instrument_slug = o.slug AND pti.person_type_slug = ANY (v_roles))
    UNION ALL
    SELECT o.category_key, o.slug, o.label, o.sort_order,
           CASE WHEN o.metadata->>'scope' = 'regional' THEN 0 ELSE 1 END
    FROM taxonomy_options o
    JOIN taxonomy_categories c ON c.key = o.category_key AND c.is_published
    WHERE o.category_key = 'genres' AND o.is_published
      AND (o.metadata->>'scope' = 'universal'
           OR EXISTS (SELECT 1 FROM genre_languages gl
                      JOIN taxonomy_options lo ON lo.category_key = 'languages' AND lo.slug = gl.language_slug
                      WHERE gl.genre_slug = o.slug AND lo.is_published
                        AND gl.language_slug = ANY (coalesce(p_languages, '{}'))))
  ),
  ranked AS (
    SELECT c.*, (row_number() OVER (PARTITION BY c.cat ORDER BY c.tier, c.rank_order))::int AS rn
    FROM candidates c
  )
  SELECT r.cat, r.opt_slug, r.opt_label, r.rn
  FROM ranked r
  WHERE r.rn <= CASE WHEN r.cat = 'genres' THEN GREATEST(p_limit, 20) ELSE p_limit END
  ORDER BY r.cat, r.rn;
END
$fn$;

GRANT EXECUTE ON FUNCTION public.persona_bucket(text, text[], text[], int) TO anon, authenticated;

DO $bucket$
DECLARE
  v_languages text[] := ARRAY(SELECT slug FROM public.taxonomy_options WHERE category_key = 'languages' AND is_published);
  v_primary text;
  v_available int;
BEGIN
  -- Any published person type will do; the genre count does not depend on it.
  SELECT o.slug INTO v_primary FROM public.taxonomy_options o
  JOIN public.taxonomy_categories c ON c.key = o.category_key AND c.is_published
  WHERE o.category_key = 'person_types' AND o.is_published ORDER BY o.sort_order LIMIT 1;
  IF v_primary IS NULL THEN
    RETURN;
  END IF;
  SELECT count(*) INTO v_available
  FROM public.taxonomy_options o
  JOIN public.taxonomy_categories c ON c.key = o.category_key AND c.is_published
  WHERE o.category_key = 'genres' AND o.is_published
    AND (o.metadata->>'scope' = 'universal'
         OR EXISTS (SELECT 1 FROM public.genre_languages gl WHERE gl.genre_slug = o.slug
                    AND gl.language_slug = ANY (v_languages)));
  IF (SELECT count(*) FROM public.persona_bucket(v_primary, '{}', v_languages, 12) b
      WHERE b.category_key = 'genres') <> LEAST(v_available, 20) THEN
    RAISE EXCEPTION 'persona_bucket: genres are not capped at 20';
  END IF;
  IF (SELECT count(*) FROM public.persona_bucket(v_primary, '{}', v_languages, 12) b
      WHERE b.category_key = 'instruments') > 12 THEN
    RAISE EXCEPTION 'persona_bucket: instruments exceed p_limit';
  END IF;
END
$bucket$;

