  v_gl jsonb := $json$[{"genre_slug":"bollywood","language_slug":"hi"},{"genre_slug":"hindustani_classical","language_slug":"hi"},{"genre_slug":"hindustani_classical","language_slug":"pa"},{"genre_slug":"hindustani_classical","language_slug":"bn"},{"genre_slug":"hindustani_classical","language_slug":"mr"},{"genre_slug":"hindustani_classical","language_slug":"gu"},{"genre_slug":"hindustani_classical","language_slug":"as"},{"genre_slug":"hindustani_classical","language_slug":"bho"},{"genre_slug":"carnatic_classical","language_slug":"ta"},{"genre_slug":"carnatic_classical","language_slug":"te"},{"genre_slug":"carnatic_classical","language_slug":"kn"},{"genre_slug":"carnatic_classical","language_slug":"ml"},{"genre_slug":"sufi_devotional","language_slug":"hi"},{"genre_slug":"sufi_devotional","language_slug":"pa"},{"genre_slug":"ghazal","language_slug":"hi"},{"genre_slug":"qawwali","language_slug":"hi"},{"genre_slug":"qawwali","language_slug":"pa"},{"genre_slug":"bhajan","language_slug":"hi"},{"genre_slug":"bhajan","language_slug":"pa"},{"genre_slug":"bhajan","language_slug":"ta"},{"genre_slug":"bhajan","language_slug":"te"},{"genre_slug":"bhajan","language_slug":"bn"},{"genre_slug":"bhajan","language_slug":"mr"},{"genre_slug":"bhajan","language_slug":"gu"},{"genre_slug":"bhajan","language_slug":"kn"},{"genre_slug":"bhajan","language_slug":"ml"},{"genre_slug":"bhajan","language_slug":"bho"},{"genre_slug":"bhajan","language_slug":"as"},{"genre_slug":"bhangra","language_slug":"pa"},{"genre_slug":"punjabi_pop","language_slug":"pa"},{"genre_slug":"rajasthani_folk","language_slug":"hi"},{"genre_slug":"bhojpuri_folk","language_slug":"bho"},{"genre_slug":"kollywood","language_slug":"ta"},{"genre_slug":"gaana","language_slug":"ta"},{"genre_slug":"tollywood","language_slug":"te"},{"genre_slug":"sandalwood","language_slug":"kn"},{"genre_slug":"mollywood","language_slug":"ml"},{"genre_slug":"rabindra_sangeet","language_slug":"bn"},{"genre_slug":"baul","language_slug":"bn"},{"genre_slug":"lavani","language_slug":"mr"},{"genre_slug":"natya_sangeet","language_slug":"mr"},{"genre_slug":"garba","language_slug":"gu"},{"genre_slug":"bihu","language_slug":"as"}]$json$;
  v_bad text;
BEGIN
  SELECT string_agg(category_key || '.' || slug || ' "' || label || '"', ', ') INTO v_bad
  FROM public.taxonomy_options WHERE label LIKE '%/%';
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'taxonomy labels still contain "/": %', v_bad;
  END IF;
  IF EXISTS (SELECT 1 FROM public.opportunities WHERE role_required LIKE '%/%') THEN
    RAISE EXCEPTION 'opportunities.role_required still contains "/"';
  END IF;
  IF EXISTS (SELECT 1 FROM public.marketplace_listings WHERE title LIKE '%/%') THEN
    RAISE EXCEPTION 'marketplace_listings.title still contains "/"';
  END IF;

  -- Old slugs are gone from the options and from every reference.
  SELECT string_agg(o.category_key || '.' || o.slug, ', ') INTO v_bad
  FROM public.taxonomy_options o WHERE v_renames->o.category_key ? o.slug;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'taxonomy rename: old options remain: %', v_bad;
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE t.roles && ARRAY(SELECT jsonb_object_keys(v_renames->'person_types'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.roles still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE t.instruments && ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.instruments still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE t.genres && ARRAY(SELECT jsonb_object_keys(v_renames->'genres'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.genres still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE EXISTS (SELECT 1 FROM unnest(t.specialisations) AS s(x) WHERE position(':' in s.x) > 1 AND v_renames->'person_types' ? split_part(s.x, ':', 1))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.specialisations still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE t.headline = ANY (ARRAY(SELECT jsonb_object_keys(v_renames->'person_types')))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.headline still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE jsonb_typeof(t.discovery_prefs->'instrumentExperience') = 'object' AND t.discovery_prefs->'instrumentExperience' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.discovery_prefs.instrumentExperience still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE jsonb_typeof(t.onboarding_draft->'primaryRole') = 'string' AND v_renames->'person_types' ? (t.onboarding_draft->>'primaryRole')) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.onboarding_draft.primaryRole still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE jsonb_typeof(t.onboarding_draft->'secondaryRoles') = 'array' AND t.onboarding_draft->'secondaryRoles' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'person_types'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.onboarding_draft.secondaryRoles still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE jsonb_typeof(t.onboarding_draft->'specialisation') = 'object' AND t.onboarding_draft->'specialisation' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'person_types'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.onboarding_draft.specialisation still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE jsonb_typeof(t.onboarding_draft->'primaryInstrument') = 'string' AND v_renames->'instruments' ? (t.onboarding_draft->>'primaryInstrument')) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.onboarding_draft.primaryInstrument still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE jsonb_typeof(t.onboarding_draft->'instruments') = 'array' AND t.onboarding_draft->'instruments' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.onboarding_draft.instruments still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE jsonb_typeof(t.onboarding_draft->'instrumentExperience') = 'object' AND t.onboarding_draft->'instrumentExperience' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.onboarding_draft.instrumentExperience still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles t WHERE jsonb_typeof(t.onboarding_draft->'genres') = 'array' AND t.onboarding_draft->'genres' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'genres'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profiles.onboarding_draft.genres still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profile_role_details t WHERE jsonb_typeof(t.details->'primary_instrument') = 'string' AND v_renames->'instruments' ? (t.details->>'primary_instrument')) THEN
    RAISE EXCEPTION 'taxonomy rename: profile_role_details.details.primary_instrument still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profile_role_details t WHERE jsonb_typeof(t.details->'secondary_instruments') = 'array' AND t.details->'secondary_instruments' ?| ARRAY(SELECT jsonb_object_keys(v_renames->'instruments'))) THEN
    RAISE EXCEPTION 'taxonomy rename: profile_role_details.details.secondary_instruments still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.opportunities t WHERE t.genres && ARRAY(SELECT jsonb_object_keys(v_renames->'genres'))) THEN
    RAISE EXCEPTION 'taxonomy rename: opportunities.genres still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profile_role_details t WHERE v_renames->'person_types' ? t.role_slug) THEN
    RAISE EXCEPTION 'taxonomy rename: profile_role_details.role_slug still holds an old slug';
  END IF;
  IF EXISTS (SELECT 1 FROM public.marketplace_listings t WHERE v_renames->'instruments' ? t.item_category) THEN
    RAISE EXCEPTION 'taxonomy rename: marketplace_listings.item_category still holds an old slug';
  END IF;

  -- person_types, instruments and genres hold exactly the generated options.
  IF EXISTS (
    SELECT 1 FROM (SELECT category_key, slug FROM public.taxonomy_options
                   WHERE category_key IN ('person_types', 'instruments', 'genres')) o
    FULL JOIN jsonb_to_recordset(v_options) AS r(category_key text, slug text)
      ON r.category_key = o.category_key AND r.slug = o.slug
    WHERE o.slug IS NULL OR r.slug IS NULL
  ) THEN
    RAISE EXCEPTION 'taxonomy rename: person_types, instruments or genres differ from the generated option set';
  END IF;

  -- The rules are exactly the generated ones (flute only under Flautist; split-out options share
  -- their parent's rules).
  IF EXISTS (
    SELECT 1 FROM public.person_type_instruments p
    FULL JOIN jsonb_to_recordset(v_pti) AS r(person_type_slug text, instrument_slug text)
      ON r.person_type_slug = p.person_type_slug AND r.instrument_slug = p.instrument_slug
    WHERE p.person_type_slug IS NULL OR r.person_type_slug IS NULL
  ) THEN
    RAISE EXCEPTION 'taxonomy rename: person_type_instruments differs from the generated rules';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.genre_languages g
    FULL JOIN jsonb_to_recordset(v_gl) AS r(genre_slug text, language_slug text)
      ON r.genre_slug = g.genre_slug AND r.language_slug = g.language_slug
    WHERE g.genre_slug IS NULL OR r.genre_slug IS NULL
  ) THEN
    RAISE EXCEPTION 'taxonomy rename: genre_languages differs from the generated rules';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.taxonomy_options WHERE category_key = 'verification_id_type' AND slug = 'company_pan')
     OR NOT EXISTS (SELECT 1 FROM public.taxonomy_options WHERE category_key = 'verification_id_type' AND slug = 'company_gstin') THEN
    RAISE EXCEPTION 'taxonomy rename: verification_id_type is missing company_pan or company_gstin';
  END IF;
END
$verify$;
